-- Paket 13.11.2026 (2): quantity buttons in catalogue cards on phones (new chunk HtsListQty, template 18). Text is hex-encoded on purpose.
SET NAMES utf8mb4;
SET SESSION group_concat_max_len = 100000;
-- ROLLBACK: removes the one line from template 18 and the chunk.
UPDATE modx_site_templates t SET t.content = REPLACE(CONVERT(t.content USING utf8mb4), _utf8mb4 0x0A2020202020202020202020202020202020202020202020205B5B244874734C6973745174795D5D, '') WHERE t.id = 18;
UPDATE modx_site_templates t SET t.content = REPLACE(CONVERT(t.content USING utf8mb4), _utf8mb4 0x5B5B244874734C6973745174795D5D, '') WHERE t.id = 18;
DELETE FROM modx_site_htmlsnippets WHERE name = 'HtsListQty' AND snippet LIKE '%htsListQtyBound%';
SELECT CASE WHEN (SELECT content FROM modx_site_templates WHERE id = 18) NOT LIKE '%[[$HtsListQty]]%' AND (SELECT COUNT(*) FROM modx_site_htmlsnippets WHERE name = 'HtsListQty') = 0 THEN _utf8mb4 0xD09AD0BDD0BED0BFD0BAD0B820D0B220D0BAD0B0D180D182D0BED187D0BAD0B0D18520D183D0B1D180D0B0D0BDD18B2C20D188D0B0D0B1D0BBD0BED0BD20D0B2D0BED0B7D0B2D180D0B0D189D191D0BD ELSE _utf8mb4 0xD09DD09520D0A1D09ED092D09FD090D094D090D095D0A220E2809420D181D182D0BED0BF2C20D181D0BAD180D0B8D0BDD188D0BED182 END AS itog;
